{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Eligible studies were full-text original clinical reports enrolling adults with initially unresectable, initially inoperable, or non-upfront-resectable hepatocellular carcinoma who received conversionintent treatment and were subsequently compared according to hepatectomy versus nonhepatectomy management. Eligible reports had to provide extractable comparative time-to-event HRs with 95% CIs for OS, PFS, EFS, DFS, or RFS, provided that the estimate explicitly isolated hepatectomy status.",
      "reason": "The review specifies the population (adults with initially unresectable HCC), intervention (conversion-intent treatment), comparator (hepatectomy vs non-hepatectomy), and outcome (time-to-event HRs for OS, PFS, EFS, DFS, or RFS) criteria."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided text does not specify eligibility criteria regarding dissemination year, language, or publication status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not explicitly distinguish between exclusion due to outcomes not being measured versus exclusion due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Fourteen comparative survival studies met the eligibility criteria and contributed 24 endpointspecific HRs comparing hepatectomy with non-hepatectomy management, including 14 OS estimates and 10 PFS/EFS estimates",
      "reason": "The review specifies the groups used in synthesis (OS and PFS/EFS) and links them to the comparison defined in the objectives (hepatectomy vs non-hepatectomy management)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Reports were excluded if they were limited to initially resectable neoadjuvant populations, postoperative adjuvant-only treatment, transplantation-only downstaging, ablation-only conversion, non-original articles, case reports, duplicate cohorts, prognostic-factor-only analyses, or regimen-comparison analyses that did not isolate hepatectomy status.",
      "reason": "The review provides specific rationales for excluding certain study types to ensure the focus remains on the specific research question regarding conversion hepatectomy."
    }
  ],
  "confidence": 95
}

